-- WEB-5.16.1: u1-l1-learn·u1-l1 문장 다양화. 빵을 먹어요 반복과 어색한 문장을 빼고 맛있어요·좋아요·커요, 대조, 은/는요? 되묻기를 넣음. Unit 1 순서는 lsn_013 과 같음 (멱등). lesson_id 유지라 진도 기록은 그대로.
-- 생성: backend/lessons/build_curriculum.py (소스 *_learn.json, *_practice.json, curriculum.csv). 직접 고치지 말 것.
-- 적용 순서: lsn_009 뒤, 번호 순서대로. concept 위젯이 들어간 앱을 먼저 배포한다. 옛 앱은 'Unknown Step Type: concept' 을 보여 주므로 옛 앱이 쓰는 DB(운영) 금지.
-- lsn_005·006·007·009 를 다시 돌리면 순서와 내용이 되돌아가므로, 그 뒤에는 이 패치도 다시 적용한다.
BEGIN;
INSERT INTO lessons (lesson_id, unit_id, unit_title, order_num, title, description,
                     difficulty_level, estimated_minutes, is_published, content, created_at, updated_at)
VALUES ('u1-l1-learn', 1, 'Introduce Yourself', 2, 'Learn: 은/는',
        'Slowly learn how 은/는 marks who or what you are talking about. Only three small checks, with no score.', 1, 5, true, '{"steps": []}'::jsonb, NOW(), NOW())
ON CONFLICT (lesson_id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description,
    estimated_minutes = EXCLUDED.estimated_minutes, is_published = EXCLUDED.is_published;
INSERT INTO lessons (lesson_id, unit_id, unit_title, order_num, title, description,
                     difficulty_level, estimated_minutes, is_published, content, created_at, updated_at)
VALUES ('u1-l1', 1, 'Introduce Yourself', 3, 'My Name is...',
        'Practice saying who you are, comparing and asking back using 은/는.', 1, 10, true, '{"steps": []}'::jsonb, NOW(), NOW())
ON CONFLICT (lesson_id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description,
    estimated_minutes = EXCLUDED.estimated_minutes, is_published = EXCLUDED.is_published;
UPDATE lessons SET content = $lsn${"steps": [{"step_type": "concept", "title": "A block you have seen", "instruction": "", "content": {"character": "turtle", "mood": "talking", "explanation": "You saw 는 in your first lesson. 저 means I, and 는 marks the topic.", "example": {"sentence": "저는 빵을 먹어요.", "translation": "I eat bread.", "tts": true, "words": [{"parts": [{"text": "저", "meaning": "I", "highlight": false}, {"text": "는", "meaning": "topic", "highlight": true}]}, {"parts": [{"text": "빵을", "meaning": "bread (object)", "highlight": false}]}, {"parts": [{"text": "먹어요", "meaning": "eat", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "concept", "title": "What is a topic?", "instruction": "", "content": {"character": "turtle", "mood": "happy", "explanation": "The topic is who or what we're talking about. Here it is 커피, and 맛있어요 means tasty.", "example": {"sentence": "커피는 맛있어요.", "translation": "The coffee is tasty.", "tts": true, "words": [{"parts": [{"text": "커피", "meaning": "coffee", "highlight": false}, {"text": "는", "meaning": "topic", "highlight": true}]}, {"parts": [{"text": "맛있어요", "meaning": "tasty", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "practice", "title": "Quick check", "instruction": "No score here. Just try it.", "content": {"graded": false, "character": "turtle", "exercises": [{"type": "fill_blank", "instruction": "The coffee is tasty.", "sentence": "커피 [ ? ] 맛있어요.", "options": ["를", "는"], "answer": "는", "feedback": {"correct": "Yes! 커피 is the topic, so it takes 는.", "incorrect": "를 goes on the thing you act on. 커피 is what we're talking about, so use 는."}}]}}, {"step_type": "concept", "title": "Say who you are", "instruction": "", "content": {"character": "turtle", "mood": "talking", "explanation": "민수 and 유미 are names. Keep 유미예요, am Yumi, whole for now, and we'll open it next lesson.", "example": {"sentence": "저는 유미예요.", "translation": "I am Yumi.", "tts": true, "words": [{"parts": [{"text": "저", "meaning": "I", "highlight": false}, {"text": "는", "meaning": "topic", "highlight": true}]}, {"parts": [{"text": "유미예요", "meaning": "am Yumi", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "concept", "title": "Same block, new name", "instruction": "", "content": {"character": "turtle", "mood": "happy", "explanation": "저, 민수 and 유미 all end in a vowel. After a vowel, the block is 는.", "example": {"sentence": "저는 민수예요.", "translation": "I am Minsu.", "tts": true, "words": [{"parts": [{"text": "저", "meaning": "I", "highlight": false}, {"text": "는", "meaning": "topic", "highlight": true}]}, {"parts": [{"text": "민수예요", "meaning": "am Minsu", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "concept", "title": "Sometimes it is 은", "instruction": "", "content": {"character": "turtle", "mood": "thinking", "explanation": "제 means my, and 이름 means name. 이름 ends in a consonant, so the block is 은, not 는.", "example": {"sentence": "제 이름은 유미예요.", "translation": "My name is Yumi.", "tts": true, "words": [{"parts": [{"text": "제", "meaning": "my", "highlight": false}]}, {"parts": [{"text": "이름", "meaning": "name", "highlight": false}, {"text": "은", "meaning": "topic", "highlight": true}]}, {"parts": [{"text": "유미예요", "meaning": "is Yumi", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "concept", "title": "How to choose", "instruction": "", "content": {"character": "turtle", "mood": "talking", "explanation": "After a consonant, use 은, like 빵, bread. After a vowel, use 는.", "example": {"sentence": "빵은 맛있어요.", "translation": "The bread is tasty.", "tts": true, "words": [{"parts": [{"text": "빵", "meaning": "bread", "highlight": false}, {"text": "은", "meaning": "topic", "highlight": true}]}, {"parts": [{"text": "맛있어요", "meaning": "tasty", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "practice", "title": "Quick check", "instruction": "No score here. Just try it.", "content": {"graded": false, "character": "turtle", "exercises": [{"type": "fill_blank", "instruction": "My name is Minsu.", "sentence": "제 이름 [ ? ] 민수예요.", "options": ["는", "은"], "answer": "은", "feedback": {"correct": "Great! 이름 ends in a consonant, so it takes 은.", "incorrect": "이름 ends in a consonant. After a consonant, use 은."}}]}}, {"step_type": "concept", "title": "It can also compare", "instruction": "", "content": {"character": "turtle", "mood": "happy", "explanation": "은/는 can also compare. Keep these whole for now: 학생이에요 is a student, 선생님이에요 is a teacher.", "example": {"sentence": "민수는 학생이에요. 유미는 선생님이에요.", "translation": "Minsu is a student. Yumi is a teacher.", "tts": true, "words": [{"parts": [{"text": "민수", "meaning": "Minsu", "highlight": false}, {"text": "는", "meaning": "topic", "highlight": true}]}, {"parts": [{"text": "학생이에요.", "meaning": "is a student", "highlight": false}]}, {"parts": [{"text": "유미", "meaning": "Yumi", "highlight": false}, {"text": "는", "meaning": "topic", "highlight": true}]}, {"parts": [{"text": "선생님이에요", "meaning": "is a teacher", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "concept", "title": "Ask back", "instruction": "", "content": {"character": "turtle", "mood": "talking", "explanation": "To ask back, put 요 after 은/는. Here 유미는요 means and Yumi?", "example": {"sentence": "민수는 학생이에요. 유미는요?", "translation": "Minsu is a student. And Yumi?", "tts": true, "words": [{"parts": [{"text": "민수", "meaning": "Minsu", "highlight": false}, {"text": "는", "meaning": "topic", "highlight": true}]}, {"parts": [{"text": "학생이에요.", "meaning": "is a student", "highlight": false}]}, {"parts": [{"text": "유미", "meaning": "Yumi", "highlight": false}, {"text": "는", "meaning": "topic", "highlight": true}, {"text": "요", "meaning": "and ...?", "highlight": true}]}]}, "tap_to_assemble": true}}, {"step_type": "practice", "title": "Quick check", "instruction": "No score here. Just try it.", "content": {"graded": false, "character": "turtle", "exercises": [{"type": "fill_blank", "instruction": "Yumi is a teacher. And Minsu?", "sentence": "유미는 선생님이에요.\n민수 [ ? ]요?", "options": ["는", "은"], "answer": "는", "feedback": {"correct": "Right! 민수 ends in a vowel, so 민수는요?", "incorrect": "민수 ends in a vowel. After a vowel, use 는."}}]}}, {"step_type": "completion", "title": "은/는 Learned!", "instruction": "Next, practice it with the rabbit.", "content": {"text": "은 and 는 mark the topic: who or what we're talking about.\nConsonant → 은 (이름은). Vowel → 는 (저는).\n은/는 can also compare, and 요 asks back: 유미는요?", "highlights": ["은", "는"]}}]}$lsn$::jsonb
WHERE lesson_id = 'u1-l1-learn';
UPDATE lessons SET content = $lsn${"steps": [{"step_type": "concept", "title": "Quick recap", "instruction": "", "content": {"character": "rabbit", "mood": "happy", "explanation": "After a consonant, use 은. After a vowel, use 는.", "example": {"sentence": "이름은 유미예요.", "translation": "My name is Yumi.", "tts": true, "words": [{"parts": [{"text": "이름", "meaning": "name", "highlight": false}, {"text": "은", "meaning": "topic", "highlight": true}]}, {"parts": [{"text": "유미예요", "meaning": "is Yumi", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "intro", "title": "Vocabulary: Meeting People", "instruction": "Tap and listen. You'll use all of these today.", "content": {"explanation": {"title": "Words for today"}, "sentences": [{"korean": "안녕하세요", "english": "Hello", "tts": true, "chunks": [{"display": "안녕하세요", "tokens": [{"text": "안녕하세요", "meaning": "hello"}]}]}, {"korean": "반가워요", "english": "Nice to meet you", "tts": true, "chunks": [{"display": "반가워요", "tokens": [{"text": "반가워요", "meaning": "nice to meet you"}]}]}, {"korean": "이름", "english": "Name", "tts": true, "chunks": [{"display": "이름", "tokens": [{"text": "이름", "meaning": "name"}]}]}, {"korean": "씨", "english": "Polite word after a name", "tts": true, "chunks": [{"display": "씨", "tokens": [{"text": "씨", "meaning": "polite word after a name"}]}]}, {"korean": "학생", "english": "Student", "tts": true, "chunks": [{"display": "학생", "tokens": [{"text": "학생", "meaning": "student"}]}]}, {"korean": "선생님", "english": "Teacher", "tts": true, "chunks": [{"display": "선생님", "tokens": [{"text": "선생님", "meaning": "teacher"}]}]}, {"korean": "빵", "english": "Bread", "tts": true, "chunks": [{"display": "빵", "tokens": [{"text": "빵", "meaning": "bread"}]}]}, {"korean": "커피", "english": "Coffee", "tts": true, "chunks": [{"display": "커피", "tokens": [{"text": "커피", "meaning": "coffee"}]}]}, {"korean": "맛있어요", "english": "Tasty", "tts": true, "chunks": [{"display": "맛있어요", "tokens": [{"text": "맛있어요", "meaning": "tasty"}]}]}, {"korean": "좋아요", "english": "Good", "tts": true, "chunks": [{"display": "좋아요", "tokens": [{"text": "좋아요", "meaning": "good"}]}]}, {"korean": "커요", "english": "Big, tall", "tts": true, "chunks": [{"display": "커요", "tokens": [{"text": "커요", "meaning": "big, tall"}]}]}]}}, {"step_type": "practice", "title": "Round 1: Spot the topic", "instruction": "은 and 는 mark who or what we're talking about.", "content": {"exercises": [{"type": "fill_blank", "instruction": "I am a student.", "sentence": "[ ? ] 학생이에요.", "options": ["저를", "저는"], "answer": "저는", "feedback": {"correct": "Correct! You're the topic, so 저는."}}, {"type": "fill_blank", "instruction": "Yumi is a teacher.", "sentence": "[ ? ] 선생님이에요.", "options": ["유미는", "유미를"], "answer": "유미는", "feedback": {"correct": "Right! Yumi is the topic, so 유미는."}}, {"type": "fill_blank", "instruction": "My name is Minsu.", "sentence": "제 [ ? ] 민수예요.", "options": ["이름을", "이름은"], "answer": "이름은", "feedback": {"correct": "Great! Your name is the topic, so 이름은."}}, {"type": "fill_blank", "instruction": "The coffee is tasty.", "sentence": "[ ? ] 맛있어요.", "options": ["커피는", "커피를"], "answer": "커피는", "feedback": {"correct": "Perfect! The coffee is the topic, so 커피는."}}, {"type": "fill_blank", "instruction": "The bread is big.", "sentence": "[ ? ] 커요.", "options": ["빵을", "빵은"], "answer": "빵은", "feedback": {"correct": "Correct! The bread is the topic, so 빵은."}}]}}, {"step_type": "practice", "title": "Round 2: 은 or 는?", "instruction": "Look at the last sound of the word.", "content": {"exercises": [{"type": "fill_blank", "instruction": "I am Minsu.", "sentence": "저 [ ? ] 민수예요.", "options": ["은", "는"], "answer": "는", "feedback": {"correct": "Correct! 저 ends in a vowel, so it takes 는."}}, {"type": "fill_blank", "instruction": "My name is Yumi.", "sentence": "제 이름 [ ? ] 유미예요.", "options": ["은", "는"], "answer": "은", "feedback": {"correct": "Right! 이름 ends in a consonant, so it takes 은."}}, {"type": "fill_blank", "instruction": "The coffee is good.", "sentence": "커피 [ ? ] 좋아요.", "options": ["는", "은"], "answer": "는", "feedback": {"correct": "Great! 커피 ends in a vowel, so it takes 는."}}, {"type": "fill_blank", "instruction": "The bread is tasty.", "sentence": "빵 [ ? ] 맛있어요.", "options": ["는", "은"], "answer": "은", "feedback": {"correct": "Perfect! 빵 ends in a consonant, so it takes 은."}}, {"type": "fill_blank", "instruction": "Minsu is tall.", "sentence": "민수 [ ? ] 커요.", "options": ["은", "는"], "answer": "는", "feedback": {"correct": "Correct! 민수 ends in a vowel, so it takes 는."}}, {"type": "fill_blank", "instruction": "The teacher is tall.", "sentence": "선생님 [ ? ] 커요.", "options": ["은", "는"], "answer": "은", "feedback": {"correct": "Right! 선생님 ends in a consonant, so it takes 은."}}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #1", "instruction": "Build the sentence: \"My name is Minsu.\" Split 은/는. 이름 ends in a consonant, so use 은.", "contentObj": {"sentence": "제 이름은 민수예요.", "translation": "My name is Minsu.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["제"], "correct_turtle": ["제"], "turtle_explanation": "Keep '제' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["이름은"], "correct_turtle": ["이름", "은"], "turtle_explanation": "'은' marks the topic. After a vowel use 는, after a consonant use 은."}, {"id": "e3", "isTarget": true, "correct_rabbit": ["민수예요"], "correct_turtle": ["민수예요"], "turtle_explanation": "Keep '민수예요' as one block — it is not this lesson's focus."}], "options": [{"id": "o1", "text": "이름은", "mode": "rabbit"}, {"id": "o2", "text": "는", "mode": "turtle"}, {"id": "o3", "text": "이름는", "mode": "rabbit"}, {"id": "o4", "text": "이름", "mode": "turtle"}, {"id": "o5", "text": "민수예요", "mode": "turtle"}, {"id": "o6", "text": "민수예요", "mode": "rabbit"}, {"id": "o7", "text": "제", "mode": "turtle"}, {"id": "o8", "text": "제", "mode": "rabbit"}, {"id": "o9", "text": "은", "mode": "turtle"}]}}, {"stepType": "agglutinative_quiz", "tit